pub fn distance(a: []const u8, b: []const u8) usize {
    var n: usize = 0;
    for (a[0..@min(a.len, b.len)], b[0..@min(a.len, b.len)]) |x, y| {
        if (x != y) n += 1;
    }
    return n;
}

