// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("point_mutations.zig");
test "Hamming distance" {
    try t.expectEqual(@as(usize, 7), m.distance("GAGCCTACTAACGGGAT", "CATCGTAATGACGGCCT"));
    try t.expectEqual(@as(usize, 0), m.distance("", ""));
    try t.expectEqual(@as(usize, 0), m.distance("ACT", "ACT"));
    try t.expectEqual(@as(usize, 1), m.distance("A", "T"));
}
test "python test_no_difference_between_empty_strands" {
    try t.expectEqual(@as(usize, 0), m.distance("", ""));
}
test "python test_no_difference_between_identical_strands" {
    try t.expectEqual(@as(usize, 0), m.distance("GGACTGA", "GGACTGA"));
}
test "python test_complete_hamming_distance_in_small_strand" {
    try t.expectEqual(@as(usize, 3), m.distance("ACT", "GGA"));
}
test "python test_hamming_distance_in_off_by_one_strand" {
    try t.expectEqual(@as(usize, 19), m.distance("GGACGGATTCTGACCTGGACTAATTTTGGGG", "AGGACGGATTCTGACCTGGACTAATTTTGGGG"));
}
test "python test_small_hamming_distance_in_middle_somewhere" {
    try t.expectEqual(@as(usize, 1), m.distance("GGACG", "GGTCG"));
}
test "python test_larger_distance" {
    try t.expectEqual(@as(usize, 2), m.distance("ACCAGGG", "ACTATGG"));
}
test "python test_ignores_extra_length_on_other_strand_when_longer" {
    try t.expectEqual(@as(usize, 3), m.distance("AAACTAGGGG", "AGGCTAGCGGTAGGAC"));
}
test "python test_ignores_extra_length_on_original_strand_when_longer" {
    try t.expectEqual(@as(usize, 5), m.distance("GACTACGGACAGGGTAGGGAAT", "GACATCGCACACC"));
}
